            ///   PATH: '~/.bin/:/usr/bin:/bin:/usr/sbin:/sbin:/usr/local/bin',
            ///   PWD: '/Users/maciej',
            ///   EDITOR: 'vim',
            ///   SHLVL: '1',
            ///   HOME: '/Users/maciej',
