            /// import { env } from 'node:process';
            ///
            /// env.test = null;
            /// console.log(env.test);
            /// // => 'null'
            /// env.test = undefined;
            /// console.log(env.test);
            /// // => 'undefined'
            /// </code>
            ///
            /// Use <c>delete</c> to delete a property from <c>process.env</c>.
            ///
            /// <code lang="js">
            /// import { env } from 'node:process';
            ///
