            /// be [safe integers](https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Number/isSafeInteger).
            ///
            /// If the <c>callback</c> function is not provided, the random integer is
            /// generated synchronously.
            ///
            /// <c></c><c>js
            /// // Asynchronous
            /// const {
            ///   randomInt,
            /// } = await import('node:crypto');
            ///
            /// randomInt(3, (err, n) => {
            ///   if (err) throw err;
            ///   console.log(</c>Random number chosen from (0, 1, 2): ${n}<c>);
            /// });
            /// <code>
            ///
            /// </code>js
            /// // Synchronous
            /// const {
            ///   randomInt,
            /// } = await import('node:crypto');
            ///
            /// const n = randomInt(3);
            /// console.log(</c>Random number chosen from (0, 1, 2): ${n}<c>);
            /// <code>
            ///
            /// </code>js
            /// // With </c>min<c> argument
            /// const {
            ///   randomInt,
            /// } = await import('node:crypto');
