            /// which are added after the trace begins will not receive future events from that trace, only future traces will be seen.
            ///
            /// <code lang="js">
            /// import diagnostics_channel from 'node:diagnostics_channel';
            /// import { AsyncLocalStorage } from 'node:async_hooks';
            ///
            /// const channels = diagnostics_channel.tracingChannel('my-channel');
            /// const myStore = new AsyncLocalStorage();
            ///
            /// // The start channel sets the initial store data to something
            /// // and stores that store data value on the trace context object
            /// channels.start.bindStore(myStore, (data) => {
            ///   const span = new Span(data);
            ///   data.span = span;
            ///   return span;
            /// });
            ///
            /// // Then asyncStart can restore from that data it stored previously
            /// channels.asyncStart.bindStore(myStore, (data) => {
            ///   return data.span;
            /// });
            /// </code>
            /// </summary>
            /// <param name="fn">
            /// callback using function to wrap a trace around
            /// </param>
            /// <param name="position">
            /// Zero-indexed argument position of expected callback
            /// </param>
            /// <param name="context">
            /// Shared object to correlate trace events through
            /// </param>
            /// <param name="thisArg">
            /// The receiver to be used for the function call
            /// </param>
            /// <param name="args">
            /// Optional arguments to pass to the function
            /// </param>
            /// <returns>
            /// The return value of the given function
            /// </returns>
            abstract member traceCallback:
                fn: System.Delegate *
