                context: 'ContextType *
                thisArg: obj *
                [<ParamArray>] args: obj[] ->
                    obj

            /// <summary>
            /// <c>true</c> if any of the individual channels has a subscriber, <c>false</c> if not.
            ///
            /// This is a helper method available on a <see href="TracingChannel">TracingChannel</see> instance to check
            /// if any of the [TracingChannel Channels](https://nodejs.org/api/diagnostics_channel.html#tracingchannel-channels) have subscribers.
            /// A <c>true</c> is returned if any of them have at least one subscriber, a <c>false</c> is returned otherwise.
            ///
            /// <code lang="js">
            /// const diagnostics_channel = require('node:diagnostics_channel');
            ///
            /// const channels = diagnostics_channel.tracingChannel('my-channel');
            ///
            /// if (channels.hasSubscribers) {
            ///   // Do something
            /// }
            /// </code>
            /// </summary>
            abstract member hasSubscribers: bool with get

        type TracingChannel<'StoreType> = TracingChannel<'StoreType, obj>

        type TracingChannel = TracingChannel<obj, obj>

        type TracingChannelSubscribers = TracingChannelSubscribers<obj>

        type TracingChannelCollection<'StoreType> = TracingChannelCollection<'StoreType, 'StoreType>

        type TracingChannelCollection = TracingChannelCollection<obj, obj>

        module TracingChannelSubscribers =

            module ``end`` =

                [<AllowNullLiteral>]
                [<Interface>]
                type message =
                    abstract member error: obj option with get, set
                    abstract member result: obj option with get, set

            module asyncStart =

                [<AllowNullLiteral>]
                [<Interface>]
                type message =
                    abstract member error: obj option with get, set
                    abstract member result: obj option with get, set

            module asyncEnd =

                [<AllowNullLiteral>]
                [<Interface>]
                type message =
                    abstract member error: obj option with get, set
                    abstract member result: obj option with get, set

            module error =

                [<AllowNullLiteral>]
                [<Interface>]
                type message =
                    abstract member error: obj with get, set

