            ///       if (err) throw err;
            ///
            ///       try {
            ///         readMyData(fd);
            ///       } finally {
            ///         close(fd, (err) => {
            ///           if (err) throw err;
            ///         });
            ///       }
            ///     });
            ///   } else {
            ///     console.error('myfile does not exist');
            ///   }
            /// });
            /// </code>
            ///
            /// **read (RECOMMENDED)**
            ///
            /// <code lang="js">
            /// import { open, close } from 'node:fs';
            ///
            /// open('myfile', 'r', (err, fd) => {
            ///   if (err) {
            ///     if (err.code === 'ENOENT') {
            ///       console.error('myfile does not exist');
            ///       return;
            ///     }
            ///
            ///     throw err;
            ///   }
            ///
            ///   try {
            ///     readMyData(fd);
            ///   } finally {
            ///     close(fd, (err) => {
            ///       if (err) throw err;
            ///     });
            ///   }
