            /// Asynchronously append data to a file, creating the file if it does not exist.
            /// </summary>
            [<ImportAll("fs")>]
            static member appendFile_: appendFile_.Exports = nativeOnly

            /// <summary>
            /// Test whether or not the given path exists by checking with the file system.
            /// Then call the <c>callback</c> argument with either true or false:
            ///
            /// <code lang="js">
            /// import { exists } from 'node:fs';
            ///
            /// exists('/etc/passwd', (e) => {
            ///   console.log(e ? 'it exists' : 'no passwd!');
            /// });
            /// </code>
            ///
            /// **The parameters for this callback are not consistent with other Node.js**
            /// **callbacks.** Normally, the first parameter to a Node.js callback is an <c>err</c> parameter, optionally followed by other parameters. The <c>fs.exists()</c> callback
            /// has only one boolean parameter. This is one reason <c>fs.access()</c> is recommended
            /// instead of <c>fs.exists()</c>.
            ///
            /// Using <c>fs.exists()</c> to check for the existence of a file before calling <c>fs.open()</c>, <c>fs.readFile()</c>, or <c>fs.writeFile()</c> is not recommended. Doing
            /// so introduces a race condition, since other processes may change the file's
            /// state between the two calls. Instead, user code should open/read/write the
            /// file directly and handle the error raised if the file does not exist.
            ///
            /// **write (NOT RECOMMENDED)**
            ///
            /// <code lang="js">
            /// import { exists, open, close } from 'node:fs';
            ///
            /// exists('myfile', (e) => {
            ///   if (e) {
            ///     console.error('myfile already exists');
            ///   } else {
            ///     open('myfile', 'wx', (err, fd) => {
            ///       if (err) throw err;
            ///
            ///       try {
            ///         writeMyData(fd);
            ///       } finally {
            ///         close(fd, (err) => {
            ///           if (err) throw err;
            ///         });
            ///       }
            ///     });
            ///   }
            /// });
            /// </code>
            ///
            /// **write (RECOMMENDED)**
            ///
            /// <code lang="js">
            /// import { open, close } from 'node:fs';
            /// open('myfile', 'wx', (err, fd) => {
            ///   if (err) {
            ///     if (err.code === 'EEXIST') {
            ///       console.error('myfile already exists');
            ///       return;
            ///     }
            ///
            ///     throw err;
            ///   }
            ///
            ///   try {
            ///     writeMyData(fd);
            ///   } finally {
            ///     close(fd, (err) => {
            ///       if (err) throw err;
            ///     });
            ///   }
            /// });
            /// </code>
            ///
            /// **read (NOT RECOMMENDED)**
            ///
            /// <code lang="js">
            /// import { open, close, exists } from 'node:fs';
            ///
            /// exists('myfile', (e) => {
            ///   if (e) {
            ///     open('myfile', 'r', (err, fd) => {
            ///       if (err) throw err;
            ///
            ///       try {
            ///         readMyData(fd);
            ///       } finally {
            ///         close(fd, (err) => {
            ///           if (err) throw err;
            ///         });
            ///       }
            ///     });
            ///   } else {
            ///     console.error('myfile does not exist');
            ///   }
            /// });
            /// </code>
            ///
            /// **read (RECOMMENDED)**
            ///
            /// <code lang="js">
            /// import { open, close } from 'node:fs';
            ///
            /// open('myfile', 'r', (err, fd) => {
            ///   if (err) {
            ///     if (err.code === 'ENOENT') {
            ///       console.error('myfile does not exist');
            ///       return;
            ///     }
            ///
            ///     throw err;
            ///   }
            ///
            ///   try {
            ///     readMyData(fd);
            ///   } finally {
            ///     close(fd, (err) => {
            ///       if (err) throw err;
            ///     });
            ///   }
            /// });
            /// </code>
            ///
            /// The "not recommended" examples above check for existence and then use the
            /// file; the "recommended" examples are better because they use the file directly
            /// and handle the error, if any.
            ///
            /// In general, check for the existence of a file only if the file won't be
            /// used directly, for example when its existence is a signal from another
            /// process.
            /// </summary>
            [<Obsolete>]
            [<ImportAll("fs")>]
            static member exists_: exists_.Exports = nativeOnly

            [<ImportAll("fs")>]
            static member constants: constants_.Exports = nativeOnly

            /// <summary>
            /// Tests a user's permissions for the file or directory specified by <c>path</c>.
            /// The <c>mode</c> argument is an optional integer that specifies the accessibility
            /// checks to be performed. <c>mode</c> should be either the value <c>fs.constants.F_OK</c> or a mask consisting of the bitwise OR of any of <c>fs.constants.R_OK</c>, <c>fs.constants.W_OK</c>, and <c>fs.constants.X_OK</c>
            /// (e.g.<c>fs.constants.W_OK | fs.constants.R_OK</c>). Check <c>File access constants</c> for
            /// possible values of <c>mode</c>.
            ///
            /// The final argument, <c>callback</c>, is a callback function that is invoked with
            /// a possible error argument. If any of the accessibility checks fail, the error
            /// argument will be an <c>Error</c> object. The following examples check if <c>package.json</c> exists, and if it is readable or writable.
            ///
            /// <c></c><c>js
            /// import { access, constants } from 'node:fs';
            ///
            /// const file = 'package.json';
            ///
            /// // Check if the file exists in the current directory.
            /// access(file, constants.F_OK, (err) => {
            ///   console.log(</c>${file} ${err ? 'does not exist' : 'exists'}<c>);
            /// });
            ///
            /// // Check if the file is readable.
            /// access(file, constants.R_OK, (err) => {
            ///   console.log(</c>${file} ${err ? 'is not readable' : 'is readable'}<c>);
            /// });
            ///
            /// // Check if the file is writable.
            /// access(file, constants.W_OK, (err) => {
            ///   console.log(</c>${file} ${err ? 'is not writable' : 'is writable'}<c>);
            /// });
            ///
            /// // Check if the file is readable and writable.
            /// access(file, constants.R_OK | constants.W_OK, (err) => {
            ///   console.log(</c>${file} ${err ? 'is not' : 'is'} readable and writable<c>);
            /// });
            /// </c><c></c>
            ///
            /// Do not use <c>fs.access()</c> to check for the accessibility of a file before calling <c>fs.open()</c>, <c>fs.readFile()</c>, or <c>fs.writeFile()</c>. Doing
            /// so introduces a race condition, since other processes may change the file's
            /// state between the two calls. Instead, user code should open/read/write the
            /// file directly and handle the error raised if the file is not accessible.
            ///
            /// **write (NOT RECOMMENDED)**
            ///
            /// <code lang="js">
            /// import { access, open, close } from 'node:fs';
            ///
            /// access('myfile', (err) => {
            ///   if (!err) {
            ///     console.error('myfile already exists');
            ///     return;
            ///   }
            ///
            ///   open('myfile', 'wx', (err, fd) => {
            ///     if (err) throw err;
            ///
            ///     try {
            ///       writeMyData(fd);
            ///     } finally {
            ///       close(fd, (err) => {
            ///         if (err) throw err;
            ///       });
            ///     }
            ///   });
            /// });
            /// </code>
            ///
            /// **write (RECOMMENDED)**
            ///
            /// <code lang="js">
            /// import { open, close } from 'node:fs';
            ///
            /// open('myfile', 'wx', (err, fd) => {
            ///   if (err) {
            ///     if (err.code === 'EEXIST') {
            ///       console.error('myfile already exists');
            ///       return;
            ///     }
            ///
            ///     throw err;
            ///   }
            ///
            ///   try {
            ///     writeMyData(fd);
            ///   } finally {
            ///     close(fd, (err) => {
            ///       if (err) throw err;
            ///     });
            ///   }
            /// });
            /// </code>
            ///
            /// **read (NOT RECOMMENDED)**
            ///
            /// <code lang="js">
            /// import { access, open, close } from 'node:fs';
            /// access('myfile', (err) => {
            ///   if (err) {
            ///     if (err.code === 'ENOENT') {
            ///       console.error('myfile does not exist');
            ///       return;
            ///     }
            ///
            ///     throw err;
            ///   }
            ///
            ///   open('myfile', 'r', (err, fd) => {
            ///     if (err) throw err;
            ///
            ///     try {
            ///       readMyData(fd);
            ///     } finally {
            ///       close(fd, (err) => {
            ///         if (err) throw err;
            ///       });
            ///     }
            ///   });
            /// });
            /// </code>
            ///
            /// **read (RECOMMENDED)**
            ///
            /// <code lang="js">
            /// import { open, close } from 'node:fs';
            ///
            /// open('myfile', 'r', (err, fd) => {
            ///   if (err) {
            ///     if (err.code === 'ENOENT') {
            ///       console.error('myfile does not exist');
            ///       return;
            ///     }
            ///
            ///     throw err;
            ///   }
            ///
            ///   try {
            ///     readMyData(fd);
            ///   } finally {
            ///     close(fd, (err) => {
            ///       if (err) throw err;
            ///     });
            ///   }
            /// });
            /// </code>
            ///
            /// The "not recommended" examples above check for accessibility and then use the
            /// file; the "recommended" examples are better because they use the file directly
            /// and handle the error, if any.
            ///
            /// In general, check for the accessibility of a file only if the file will not be
            /// used directly, for example when its accessibility is a signal from another
            /// process.
            ///
            /// On Windows, access-control policies (ACLs) on a directory may limit access to
            /// a file or directory. The <c>fs.access()</c> function, however, does not check the
            /// ACL and therefore may report that a path is accessible even if the ACL restricts
            /// the user from reading or writing to it.
            /// Asynchronously tests a user's permissions for the file specified by path.
            /// </summary>
            [<ImportAll("fs")>]
            static member access_: access_.Exports = nativeOnly

            /// <summary>
            /// Forces all currently queued I/O operations associated with the file to the
