        /// <summary>
        /// Valid types for path values in "fs".
        /// </summary>
        type PathLike = U3<string, Node.Buffer, Node.url.URL>

        type PathOrFileDescriptor = U2<Node.fs.PathLike, float>

        type TimeLike = U3<string, float, Date>

        type NoParamCallback = delegate of err: Node.NodeJS.ErrnoException option -> unit

        [<RequireQualifiedAccess>]
        [<Erase(CaseRules.None)>]
        type BufferEncodingOption =
            | buffer
            | Case1 of BufferEncodingOption.Cases.Case1

        [<AllowNullLiteral>]
        [<Interface>]
        type ObjectEncodingOptions =
            abstract member encoding: Node.BufferEncoding option with get, set

        type EncodingOption = U2<Node.fs.ObjectEncodingOptions, Node.BufferEncoding> option

        type OpenMode = U2<float, string>

        type Mode = U2<float, string>

        [<AllowNullLiteral>]
        [<Interface>]
        type StatsBase<'T> =
            abstract member isFile: unit -> bool
            abstract member isDirectory: unit -> bool
            abstract member isBlockDevice: unit -> bool
            abstract member isCharacterDevice: unit -> bool
            abstract member isSymbolicLink: unit -> bool
            abstract member isFIFO: unit -> bool
            abstract member isSocket: unit -> bool
            abstract member dev: 'T with get, set
            abstract member ino: 'T with get, set
            abstract member mode: 'T with get, set
            abstract member nlink: 'T with get, set
            abstract member uid: 'T with get, set
            abstract member gid: 'T with get, set
            abstract member rdev: 'T with get, set
            abstract member size: 'T with get, set
            abstract member blksize: 'T with get, set
            abstract member blocks: 'T with get, set
            abstract member atimeMs: 'T with get, set
            abstract member mtimeMs: 'T with get, set
            abstract member ctimeMs: 'T with get, set
            abstract member birthtimeMs: 'T with get, set
            abstract member atime: Date with get, set
            abstract member mtime: Date with get, set
            abstract member ctime: Date with get, set
            abstract member birthtime: Date with get, set

        /// <summary>
        /// A <c>fs.Stats</c> object provides information about a file.
        ///
        /// Objects returned from <see href="stat">stat</see>, <see href="lstat">lstat</see>, <see href="fstat">fstat</see>, and
        /// their synchronous counterparts are of this type.
        /// If <c>bigint</c> in the <c>options</c> passed to those methods is true, the numeric values
        /// will be <c>bigint</c> instead of <c>number</c>, and the object will contain additional
        /// nanosecond-precision properties suffixed with <c>Ns</c>. <c>Stat</c> objects are not to be created directly using the <c>new</c> keyword.
        ///
        /// <code lang="console">
        /// Stats {
        ///   dev: 2114,
        ///   ino: 48064969,
        ///   mode: 33188,
        ///   nlink: 1,
        ///   uid: 85,
        ///   gid: 100,
        ///   rdev: 0,
        ///   size: 527,
        ///   blksize: 4096,
        ///   blocks: 8,
        ///   atimeMs: 1318289051000.1,
        ///   mtimeMs: 1318289051000.1,
        ///   ctimeMs: 1318289051000.1,
        ///   birthtimeMs: 1318289051000.1,
        ///   atime: Mon, 10 Oct 2011 23:24:11 GMT,
        ///   mtime: Mon, 10 Oct 2011 23:24:11 GMT,
        ///   ctime: Mon, 10 Oct 2011 23:24:11 GMT,
        ///   birthtime: Mon, 10 Oct 2011 23:24:11 GMT }
        /// </code>
        ///
        /// <c>bigint</c> version:
        ///
        /// <code lang="console">
        /// BigIntStats {
        ///   dev: 2114n,
        ///   ino: 48064969n,
        ///   mode: 33188n,
        ///   nlink: 1n,
        ///   uid: 85n,
        ///   gid: 100n,
        ///   rdev: 0n,
        ///   size: 527n,
        ///   blksize: 4096n,
        ///   blocks: 8n,
        ///   atimeMs: 1318289051000n,
        ///   mtimeMs: 1318289051000n,
        ///   ctimeMs: 1318289051000n,
        ///   birthtimeMs: 1318289051000n,
        ///   atimeNs: 1318289051000000000n,
        ///   mtimeNs: 1318289051000000000n,
        ///   ctimeNs: 1318289051000000000n,
        ///   birthtimeNs: 1318289051000000000n,
        ///   atime: Mon, 10 Oct 2011 23:24:11 GMT,
