            /// <summary>
            /// Since most requests are GET requests without bodies, Node.js provides this
            /// convenience method. The only difference between this method and <see href="request">request</see> is that it sets the method to GET by default and calls <c>req.end()</c> automatically. The callback must take care to
            /// consume the response
            /// data for reasons stated in <see href="ClientRequest">ClientRequest</see> section.
            ///
            /// The <c>callback</c> is invoked with a single argument that is an instance of <see href="IncomingMessage">IncomingMessage</see>.
            ///
            /// JSON fetching example:
            ///
            /// <c></c><c>js
            /// http.get('http://localhost:8000/', (res) => {
            ///   const { statusCode } = res;
            ///   const contentType = res.headers['content-type'];
            ///
            ///   let error;
            ///   // Any 2xx status code signals a successful response but
            ///   // here we're only checking for 200.
            ///   if (statusCode !== 200) {
            ///     error = new Error('Request Failed.\n' +
            ///                       </c>Status Code: ${statusCode}<c>);
            ///   } else if (!/^application\/json/.test(contentType)) {
            ///     error = new Error('Invalid content-type.\n' +
            ///                       </c>Expected application/json but received ${contentType}<c>);
            ///   }
            ///   if (error) {
            ///     console.error(error.message);
            ///     // Consume response data to free up memory
            ///     res.resume();
            ///     return;
            ///   }
            ///
            ///   res.setEncoding('utf8');
            ///   let rawData = '';
            ///   res.on('data', (chunk) => { rawData += chunk; });
            ///   res.on('end', () => {
            ///     try {
            ///       const parsedData = JSON.parse(rawData);
            ///       console.log(parsedData);
            ///     } catch (e) {
            ///       console.error(e.message);
            ///     }
            ///   });
            /// }).on('error', (e) => {
            ///   console.error(</c>Got error: ${e.message}<c>);
            /// });
            ///
            /// // Create a local server to receive data from
            /// const server = http.createServer((req, res) => {
            ///   res.writeHead(200, { 'Content-Type': 'application/json' });
            ///   res.end(JSON.stringify({
            ///     data: 'Hello World!',
            ///   }));
            /// });
            ///
            /// server.listen(8000);
            /// </c><c></c>
            /// </summary>
            /// <param name="options">
            /// Accepts the same <c>options</c> as <see href="request">request</see>, with the method set to GET by default.
            /// </param>
