            /// If wait is <c>true</c>, will block until a client has connected to the inspect port
            /// and flow control has been passed to the debugger client.
            ///
            /// See the [security warning](https://nodejs.org/docs/latest-v22.x/api/cli.html#warning-binding-inspector-to-a-public-ipport-combination-is-insecure)
            /// regarding the <c>host</c> parameter usage.
            /// </summary>
            /// <param name="port">
            /// Port to listen on for inspector connections. Defaults to what was specified on the CLI.
            /// </param>
            /// <param name="host">
            /// Host to listen on for inspector connections. Defaults to what was specified on the CLI.
            /// </param>
            /// <param name="wait">
            /// Block until a client has connected. Defaults to what was specified on the CLI.
            /// </param>
            /// <returns>
            /// Disposable that calls <c>inspector.close()</c>.
            /// </returns>
            [<Import("open", "inspector")>]
            static member ``open``(?port: float, ?host: string, ?wait: bool) : obj = nativeOnly

            /// <summary>
            /// Deactivate the inspector. Blocks until there are no active connections.
            /// </summary>
            [<Import("close", "inspector")>]
            static member close() : unit = nativeOnly

            /// <summary>
            /// Return the URL of the active inspector, or <c>undefined</c> if there is none.
            ///
            /// <code lang="console">
            /// $ node --inspect -p 'inspector.url()'
            /// Debugger listening on ws://127.0.0.1:9229/166e272e-7a30-4d09-97ce-f1c012b43c34
            /// For help, see: https://nodejs.org/en/docs/inspector
            /// ws://127.0.0.1:9229/166e272e-7a30-4d09-97ce-f1c012b43c34
            ///
            /// $ node --inspect=localhost:3000 -p 'inspector.url()'
            /// Debugger listening on ws://localhost:3000/51cf8d0e-3c36-4c59-8efd-54519839e56a
            /// For help, see: https://nodejs.org/en/docs/inspector
            /// ws://localhost:3000/51cf8d0e-3c36-4c59-8efd-54519839e56a
            ///
            /// $ node -p 'inspector.url()'
