            /// <summary>
            /// Adds a rule to block a range of IP addresses from <c>start</c> (inclusive) to<c>end</c> (inclusive).
            /// </summary>
            /// <param name="start">
            /// The starting IPv4 or IPv6 address in the range.
            /// </param>
            /// <param name="end">
            /// The ending IPv4 or IPv6 address in the range.
            /// </param>
            /// <param name="type">
            /// Either <c>'ipv4'</c> or <c>'ipv6'</c>.
            /// </param>
            abstract member addRange:
                start: string * ``end``: string * ?``type``: Node.net.IPVersion -> unit

            /// <summary>
            /// Adds a rule to block a range of IP addresses from <c>start</c> (inclusive) to<c>end</c> (inclusive).
            /// </summary>
            abstract member addRange:
                start: Node.net.SocketAddress * ``end``: Node.net.SocketAddress -> unit

            /// <summary>
            /// Adds a rule to block a range of IP addresses specified as a subnet mask.
            /// </summary>
            /// <param name="net">
            /// The network IPv4 or IPv6 address.
            /// </param>
            /// <param name="prefix">
            /// The number of CIDR prefix bits. For IPv4, this must be a value between <c>0</c> and <c>32</c>. For IPv6, this must be between <c>0</c> and <c>128</c>.
            /// </param>
            /// <param name="type">
            /// Either <c>'ipv4'</c> or <c>'ipv6'</c>.
            /// </param>
            abstract member addSubnet: net: Node.net.SocketAddress * prefix: float -> unit

            /// <summary>
            /// Adds a rule to block a range of IP addresses specified as a subnet mask.
            /// </summary>
            abstract member addSubnet:
                net: string * prefix: float * ?``type``: Node.net.IPVersion -> unit

            /// <summary>
            /// Returns <c>true</c> if the given IP address matches any of the rules added to the<c>BlockList</c>.
            ///
            /// <code lang="js">
            /// const blockList = new net.BlockList();
            /// blockList.addAddress('123.123.123.123');
            /// blockList.addRange('10.0.0.1', '10.0.0.10');
            /// blockList.addSubnet('8592:757c:efae:4e45::', 64, 'ipv6');
            ///
            /// console.log(blockList.check('123.123.123.123'));  // Prints: true
            /// console.log(blockList.check('10.0.0.3'));  // Prints: true
            /// console.log(blockList.check('222.111.111.222'));  // Prints: false
            ///
            /// // IPv6 notation for IPv4 addresses works:
            /// console.log(blockList.check('::ffff:7b7b:7b7b', 'ipv6')); // Prints: true
            /// console.log(blockList.check('::ffff:123.123.123.123', 'ipv6')); // Prints: true
            /// </code>
            /// </summary>
            /// <param name="address">
            /// The IP address to check
            /// </param>
            /// <param name="type">
            /// Either <c>'ipv4'</c> or <c>'ipv6'</c>.
            /// </param>
            abstract member check: address: Node.net.SocketAddress -> bool
            /// <summary>
            /// Returns <c>true</c> if the given IP address matches any of the rules added to the<c>BlockList</c>.
            ///
            /// <code lang="js">
            /// const blockList = new net.BlockList();
            /// blockList.addAddress('123.123.123.123');
            /// blockList.addRange('10.0.0.1', '10.0.0.10');
            /// blockList.addSubnet('8592:757c:efae:4e45::', 64, 'ipv6');
            ///
            /// console.log(blockList.check('123.123.123.123'));  // Prints: true
            /// console.log(blockList.check('10.0.0.3'));  // Prints: true
            /// console.log(blockList.check('222.111.111.222'));  // Prints: false
            ///
            /// // IPv6 notation for IPv4 addresses works:
            /// console.log(blockList.check('::ffff:7b7b:7b7b', 'ipv6')); // Prints: true
            /// console.log(blockList.check('::ffff:123.123.123.123', 'ipv6')); // Prints: true
            /// </code>
            /// </summary>
            abstract member check: address: string * ?``type``: Node.net.IPVersion -> bool
            /// <summary>
            /// The list of rules added to the blocklist.
            /// </summary>
            abstract member rules: ReadonlyArray<string> with get, set

            /// <summary>
