            /// <param name="value">
            /// Any JS value
            /// </param>
            static member inline isBlockList(value: obj) : bool =
                emitJsExpr
                    (value)
                    $$"""
import { BlockList } from "net";
BlockList.isBlockList($0)"""

            /// <summary>
            /// <code lang="js">
            /// const blockList = new net.BlockList();
            /// const data = [
            ///   'Subnet: IPv4 192.168.1.0/24',
            ///   'Address: IPv4 10.0.0.5',
            ///   'Range: IPv4 192.168.2.1-192.168.2.10',
            ///   'Range: IPv4 10.0.0.1-10.0.0.10',
            /// ];
            /// blockList.fromJSON(data);
            /// blockList.fromJSON(JSON.stringify(data));
            /// </code>
            /// </summary>
            abstract member fromJSON: data: string -> unit
            /// <summary>
            /// <code lang="js">
            /// const blockList = new net.BlockList();
            /// const data = [
            ///   'Subnet: IPv4 192.168.1.0/24',
            ///   'Address: IPv4 10.0.0.5',
            ///   'Range: IPv4 192.168.2.1-192.168.2.10',
            ///   'Range: IPv4 10.0.0.1-10.0.0.10',
            /// ];
            /// blockList.fromJSON(data);
            /// blockList.fromJSON(JSON.stringify(data));
            /// </code>
            /// </summary>
            abstract member fromJSON: data: ResizeArray<string> -> unit
            abstract member toJSON: unit -> ReadonlyArray<string>

