            ///     console.log(</c>Script Name: ${callSite.scriptName}<c>);
            ///     console.log(</c>Line Number: ${callSite.lineNumber}<c>);
            ///     console.log(</c>Column Number: ${callSite.column}<c>);
            ///   });
            ///   // CallSite 1:
            ///   // Function Name: exampleFunction
            ///   // Script Name: /home/example.js
            ///   // Line Number: 5
            ///   // Column Number: 26
            ///
            ///   // CallSite 2:
            ///   // Function Name: anotherFunction
            ///   // Script Name: /home/example.js
            ///   // Line Number: 22
            ///   // Column Number: 3
            ///
            ///   // ...
