            /// <summary>
            /// The <c>util.inspect()</c> method returns a string representation of <c>object</c> that is
            /// intended for debugging. The output of <c>util.inspect</c> may change at any time
            /// and should not be depended upon programmatically. Additional <c>options</c> may be
            /// passed that alter the result.
            /// <c>util.inspect()</c> will use the constructor's name and/or <c>Symbol.toStringTag</c>
            /// property to make an identifiable tag for an inspected value.
            ///
            /// <code lang="js">
            /// class Foo {
            ///   get [Symbol.toStringTag]() {
            ///     return 'bar';
            ///   }
            /// }
            ///
            /// class Bar {}
            ///
            /// const baz = Object.create(null, { [Symbol.toStringTag]: { value: 'foo' } });
            ///
            /// util.inspect(new Foo()); // 'Foo [bar] {}'
            /// util.inspect(new Bar()); // 'Bar {}'
            /// util.inspect(baz);       // '[foo] {}'
            /// </code>
            ///
            /// Circular references point to their anchor by using a reference index:
            ///
            /// <code lang="js">
            /// import { inspect } from 'node:util';
            ///
            /// const obj = {};
            /// obj.a = [obj];
            /// obj.b = {};
            /// obj.b.inner = obj.b;
            /// obj.b.obj = obj;
            ///
            /// console.log(inspect(obj));
            /// // <ref *1> {
            /// //   a: [ [Circular *1] ],
            /// //   b: <ref *2> { inner: [Circular *2], obj: [Circular *1] }
            /// // }
            /// </code>
            ///
            /// The following example inspects all properties of the <c>util</c> object:
            ///
            /// <code lang="js">
            /// import util from 'node:util';
            ///
            /// console.log(util.inspect(util, { showHidden: true, depth: null }));
            /// </code>
            ///
            /// The following example highlights the effect of the <c>compact</c> option:
            ///
            /// <c></c><c>js
            /// import { inspect } from 'node:util';
            ///
            /// const o = {
            ///   a: [1, 2, [[
            ///     'Lorem ipsum dolor sit amet,\nconsectetur adipiscing elit, sed do ' +
            ///       'eiusmod \ntempor incididunt ut labore et dolore magna aliqua.',
            ///     'test',
            ///     'foo']], 4],
            ///   b: new Map([['za', 1], ['zb', 'test']]),
            /// };
            /// console.log(inspect(o, { compact: true, depth: 5, breakLength: 80 }));
            ///
            /// // { a:
            /// //   [ 1,
            /// //     2,
            /// //     [ [ 'Lorem ipsum dolor sit amet,\nconsectetur [...]', // A long line
            /// //           'test',
            /// //           'foo' ] ],
            /// //     4 ],
            /// //   b: Map(2) { 'za' => 1, 'zb' => 'test' } }
            ///
            /// // Setting </c>compact<c> to false or an integer creates more reader friendly output.
            /// console.log(inspect(o, { compact: false, depth: 5, breakLength: 80 }));
            ///
            /// // {
            /// //   a: [
            /// //     1,
            /// //     2,
            /// //     [
            /// //       [
            /// //         'Lorem ipsum dolor sit amet,\n' +
            /// //           'consectetur adipiscing elit, sed do eiusmod \n' +
            /// //           'tempor incididunt ut labore et dolore magna aliqua.',
            /// //         'test',
            /// //         'foo'
            /// //       ]
            /// //     ],
            /// //     4
            /// //   ],
            /// //   b: Map(2) {
            /// //     'za' => 1,
            /// //     'zb' => 'test'
            /// //   }
            /// // }
            ///
            /// // Setting </c>breakLength<c> to e.g. 150 will print the "Lorem ipsum" text in a
            /// // single line.
            /// </c><c></c>
            ///
            /// The <c>showHidden</c> option allows <c>WeakMap</c> and <c>WeakSet</c> entries to be
            /// inspected. If there are more entries than <c>maxArrayLength</c>, there is no
            /// guarantee which entries are displayed. That means retrieving the same
            /// <c>WeakSet</c> entries twice may result in different output. Furthermore, entries
            /// with no remaining strong references may be garbage collected at any time.
            ///
            /// <code lang="js">
            /// import { inspect } from 'node:util';
            ///
            /// const obj = { a: 1 };
            /// const obj2 = { b: 2 };
            /// const weakSet = new WeakSet([obj, obj2]);
            ///
            /// console.log(inspect(weakSet, { showHidden: true }));
            /// // WeakSet { { a: 1 }, { b: 2 } }
            /// </code>
            ///
            /// The <c>sorted</c> option ensures that an object's property insertion order does not
            /// impact the result of <c>util.inspect()</c>.
            ///
            /// <c></c><c>js
            /// import { inspect } from 'node:util';
            /// import assert from 'node:assert';
            ///
            /// const o1 = {
            ///   b: [2, 3, 1],
            ///   a: '</c>a<c> comes before </c>b<c>',
            ///   c: new Set([2, 3, 1]),
            /// };
            /// console.log(inspect(o1, { sorted: true }));
            /// // { a: '</c>a<c> comes before </c>b<c>', b: [ 2, 3, 1 ], c: Set(3) { 1, 2, 3 } }
            /// console.log(inspect(o1, { sorted: (a, b) => b.localeCompare(a) }));
            /// // { c: Set(3) { 3, 2, 1 }, b: [ 2, 3, 1 ], a: '</c>a<c> comes before </c>b<c>' }
            ///
            /// const o2 = {
            ///   c: new Set([2, 1, 3]),
            ///   a: '</c>a<c> comes before </c>b<c>',
            ///   b: [2, 3, 1],
            /// };
            /// assert.strict.equal(
            ///   inspect(o1, { sorted: true }),
            ///   inspect(o2, { sorted: true }),
            /// );
            /// </c><c></c>
            ///
            /// The <c>numericSeparator</c> option adds an underscore every three digits to all
            /// numbers.
            ///
            /// <code lang="js">
            /// import { inspect } from 'node:util';
            ///
            /// const thousand = 1000;
            /// const million = 1000000;
            /// const bigNumber = 123456789n;
            /// const bigDecimal = 1234.12345;
            ///
            /// console.log(inspect(thousand, { numericSeparator: true }));
            /// // 1_000
            /// console.log(inspect(million, { numericSeparator: true }));
            /// // 1_000_000
            /// console.log(inspect(bigNumber, { numericSeparator: true }));
            /// // 123_456_789n
            /// console.log(inspect(bigDecimal, { numericSeparator: true }));
            /// // 1_234.123_45
            /// </code>
            ///
            /// <c>util.inspect()</c> is a synchronous method intended for debugging. Its maximum
            /// output length is approximately 128 MiB. Inputs that result in longer output will
            /// be truncated.
            /// </summary>
            [<ImportAll("util")>]
            static member inspect_: inspect_.Exports = nativeOnly

            /// <summary>
            /// Takes a function following the common error-first callback style, i.e. taking
            /// an <c>(err, value) => ...</c> callback as the last argument, and returns a version
            /// that returns promises.
            ///
            /// <c></c><c>js
            /// import { promisify } from 'node:util';
            /// import { stat } from 'node:fs';
            ///
            /// const promisifiedStat = promisify(stat);
            /// promisifiedStat('.').then((stats) => {
            ///   // Do something with </c>stats<c>
            /// }).catch((error) => {
            ///   // Handle the error.
            /// });
            /// </c><c></c>
            ///
            /// Or, equivalently using <c>async function</c>s:
            ///
            /// <c></c><c>js
            /// import { promisify } from 'node:util';
            /// import { stat } from 'node:fs';
            ///
            /// const promisifiedStat = promisify(stat);
            ///
            /// async function callStat() {
            ///   const stats = await promisifiedStat('.');
            ///   console.log(</c>This directory is owned by ${stats.uid}<c>);
            /// }
            ///
            /// callStat();
            /// </c><c></c>
            ///
            /// If there is an <c>original[util.promisify.custom]</c> property present, <c>promisify</c>
            /// will return its value, see [Custom promisified functions](https://nodejs.org/docs/latest-v22.x/api/util.html#custom-promisified-functions).
            ///
            /// <c>promisify()</c> assumes that <c>original</c> is a function taking a callback as its
            /// final argument in all cases. If <c>original</c> is not a function, <c>promisify()</c>
            /// will throw an error. If <c>original</c> is a function but its last argument is not
            /// an error-first callback, it will still be passed an error-first
            /// callback as its last argument.
            ///
            /// Using <c>promisify()</c> on class methods or other methods that use <c>this</c> may not
            /// work as expected unless handled specially:
            ///
            /// <code lang="js">
            /// import { promisify } from 'node:util';
            ///
            /// class Foo {
            ///   constructor() {
            ///     this.a = 42;
            ///   }
            ///
            ///   bar(callback) {
            ///     callback(null, this.a);
            ///   }
            /// }
            ///
            /// const foo = new Foo();
            ///
            /// const naiveBar = promisify(foo.bar);
            /// // TypeError: Cannot read properties of undefined (reading 'a')
            /// // naiveBar().then(a => console.log(a));
            ///
            /// naiveBar.call(foo).then((a) => console.log(a)); // '42'
            ///
            /// const bindBar = naiveBar.bind(foo);
            /// bindBar().then((a) => console.log(a)); // '42'
            /// </code>
            /// </summary>
            [<ImportAll("util")>]
            static member promisify_: promisify_.Exports = nativeOnly

            [<ImportAll("util/types")>]
            static member util_SLASH_types: util_SLASH_types_.Exports = nativeOnly

        [<AllowNullLiteral>]
        [<Interface>]
        type InspectOptions =
            /// <summary>
            /// If <c>true</c>, object's non-enumerable symbols and properties are included in the formatted result.
            /// <c>WeakMap</c> and <c>WeakSet</c> entries are also included as well as user defined prototype properties (excluding method properties).
            /// </summary>
            abstract member showHidden: bool option with get, set
            /// <summary>
            /// Specifies the number of times to recurse while formatting object.
            /// This is useful for inspecting large objects.
            /// To recurse up to the maximum call stack size pass <c>Infinity</c> or <c>null</c>.
            /// </summary>
            abstract member depth: float option with get, set
            /// <summary>
            /// If <c>true</c>, the output is styled with ANSI color codes. Colors are customizable.
            /// </summary>
            abstract member colors: bool option with get, set
            /// <summary>
            /// If <c>false</c>, <c>[util.inspect.custom](depth, opts, inspect)</c> functions are not invoked.
            /// </summary>
            abstract member customInspect: bool option with get, set
            /// <summary>
            /// If <c>true</c>, <c>Proxy</c> inspection includes the target and handler objects.
            /// </summary>
            abstract member showProxy: bool option with get, set
            /// <summary>
            /// Specifies the maximum number of <c>Array</c>, <c>TypedArray</c>, <c>WeakMap</c>, and <c>WeakSet</c> elements
            /// to include when formatting. Set to <c>null</c> or <c>Infinity</c> to show all elements.
